client_script:
frappe.web_form.after_load = function() {
  if (frappe.web_form.fields_dict.chauffeur) { frappe.web_form.fields_dict.chauffeur.get_query = function(){ return { query: 'kya_hr.api.delegataire_query' }; }; }
  var doc = frappe.web_form.doc;
  if (doc && !doc.date_plein) { frappe.web_form.set_value('date_plein', frappe.datetime.get_today()); }
  if (doc && doc.name && !String(doc.name).startsWith('new')) {
    var refEl = document.createElement('div');
    refEl.innerHTML = '<div style="margin-bottom:12px;padding:8px 16px;background:#fff3e0;color:#e65100;border-left:4px solid #fb8c00;border-radius:6px;display:inline-block;font-weight:700;font-size:14px;">\u26FD R\u00e9f. : ' + doc.name + (doc.prix_litre ? '  \u2014  ' + doc.prix_litre + ' FCFA/L' : '') + '</div>';
    var w = document.querySelector('.web-form-wrapper') || document.querySelector('.container');
    if (w) w.prepend(refEl);
  }
};
